  renderRepair(message, html);
  renderAdventuring(message, html);
  renderRegulated(message, html);
  renderCreate(message, html);
  renderPendingRoll(message, html);
  renderUpkeep(message, html);
  renderBind(message, html);
  renderVolleyball(message, html);
  renderLifeforce(message, html);
  renderMaterialize(message, html);
  renderGearHazard(message, html);
  renderGearScan(message, html);
  renderGearSpikes(message, html);
  renderArmsHit(message, html);
  renderFakeDeath(message, html);
  renderMeteor(message, html);
  renderMeteorHit(message, html);
  renderMeteorStrike(message, html);
  renderLoss(message, html);
  renderHealing(message, html);
  renderShock(message, html);
  renderIllusion(message, html);
  renderDebilitated(message, html);
  renderParaPara(message, html);
  renderPetrify(message, html);
